import{z as s,x as o,o as t,c as p,q as r,j as i,D as l,d as E,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"驱逐策略与启发式","description":"","frontmatter":{"title":"驱逐策略与启发式","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-eviction-heuristics.md","filePath":"llm/kv-eviction-heuristics.md","lastUpdated":1791063341000}'),d={name:"llm/kv-eviction-heuristics.md"};function m(h,a,C,c,F,f){const A=o("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="驱逐策略与启发式" tabindex="-1">驱逐策略与启发式 <a class="header-anchor" href="#驱逐策略与启发式" aria-label="Permalink to &quot;驱逐策略与启发式&quot;">​</a></h1><div class="epigraph"><p>每条驱逐启发式都是同一个三段式：给历史打重要性分，给新来者留保护期，然后把分数最低者不可逆地扔掉。</p><footer>—— 据 Zhang et al., H2O, NeurIPS 2023；Xiao et al., StreamingLLM, ICLR 2024 的策略结构整理</footer></div><p><a href="/llm/kv-layerwise-sensitivity">上一课</a>把预算按层按头重排，隐含的前提是预算必须先存在：长度受控、每 token 字节受控之后还不够，就要丢历史。本课写丢的规则。各配方的机制已分别写过——<a href="/llm/kv-eviction">窗口与 sink</a>、<a href="/llm/h2o-kv">H2O</a>、<a href="/llm/snapkv">SnapKV</a>、<a href="/llm/quest-kv">QUEST</a>——本课收拢成一张谱系表：启发式之间怎么比、按什么选、错在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预算 \\(k\\) 小于当前长度 \\(t\\) 时，必须选一个可见子集 \\(S_t\\)，此后 softmax 只在 \\(S_t\\) 上归一化。选错的代价不可逆：被丢的键不再参与任何点积，将来即使变成关键也找不回来。所有启发式因此都在回答同一道题——<strong>用现在的信息估计「未来的注意力会打给谁」</strong>。估计是免不了的：未来查询还没出现。差别只在估计器用什么信号、给谁上保险。</p><p>还有一套容易混淆的「驱逐」：页池压力下逐出无引用的<a href="/llm/kv-prefix-cache">前缀缓存</a>页，按 LRU 走。那改变的是「哪些字节住在 HBM」，不改任何请求的可见集，与本课的可见集驱逐分属两本账，混写会让「命中率」与「任务质量」互相背锅。</p><p><span class="marginnote">术语翻译：页池逐出像图书馆把没人借的书搬去地下库——书还在，要时能调回来；可见集驱逐像把那几页直接撕掉——模型从此看不见这段内容。两者都叫 eviction，后果天差地别。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按估计信号排成谱系。</p><ul><li><strong>位置即分数</strong>：滑动窗口加 sink 禁逐。零统计成本、最稳，代价是中间历史整段丢失。适合「只要当前句稳定、缓存常数」的流式场景（配方见 <a href="/llm/streaming-kv">StreamingLLM 策略</a>）。</li><li><strong>累积注意力当分数</strong>：<a href="/llm/h2o-kv">H2O</a> 在线累积每个位置的注意力质量，驱逐非窗口内分数最低者。能保住中部的实体锚点，但分数偏向活得久的位置，新出现的专名要靠 recent 保护期救。</li><li><strong>提前投票</strong>：<a href="/llm/snapkv">SnapKV</a> 用提示末段的观察窗预选前缀簇，在生成开始前完成压缩。适合「提示长、生成短」的问答负载；代价是选完即锁，长生成中途需要的新证据进不来。</li><li><strong>不删，挑着读</strong>：<a href="/llm/quest-kv">QUEST</a> 保留全部 KV，按当前查询挑页加载。没有失忆，失败模式是召回不足；前提是查询在 decode 前已知。</li></ul><p>选型判据三条：未来查询是否已知（已知走 query-aware，未知只能预测性驱逐）；提示与生成的长度比（长提示短生成偏好 SnapKV，长生成偏好 H2O 式在线）；允许多大的任务质量损失。</p>',11)),(t(),i(B,null,{default:l(()=>[n(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUDGET%5B%22%E9%A2%84%E7%AE%97%20k%20%3C%20t%22%5D%20--%3E%20Q%7B%22%E6%9C%AA%E6%9D%A5%E6%9F%A5%E8%AF%A2%E5%B7%B2%E7%9F%A5%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%B7%B2%E7%9F%A5%7C%20QA%5B%22%E6%8C%91%E9%A1%B5%E5%8A%A0%E8%BD%BD%EF%BC%9AQUEST%20%E4%B8%80%E7%B1%BB%22%5D%0A%20%20Q%20--%3E%7C%E6%9C%AA%E7%9F%A5%7C%20SIG%7B%22%E7%94%A8%E4%BB%80%E4%B9%88%E4%BF%A1%E5%8F%B7%E4%BC%B0%E8%AE%A1%E9%87%8D%E8%A6%81%E6%80%A7%22%7D%0A%20%20SIG%20--%3E%7C%E4%BD%8D%E7%BD%AE%7C%20WIN%5B%22%E6%BB%91%E7%AA%97%20%2B%20sink%20%E7%A6%81%E9%80%90%22%5D%0A%20%20SIG%20--%3E%7C%E5%9C%A8%E7%BA%BF%E7%B4%AF%E7%A7%AF%7C%20H2%5B%22H2O%EF%BC%9AH2%20%2B%20recent%22%5D%0A%20%20SIG%20--%3E%7C%E6%8F%90%E7%A4%BA%E6%9C%AB%E6%AE%B5%E6%8A%95%E7%A5%A8%7C%20SNAP%5B%22SnapKV%20%E9%A2%84%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20WIN%20--%3E%20EVAL%5B%22%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E4%BB%BB%E5%8A%A1%E9%AA%8C%E6%94%B6%22%5D%0A%20%20H2%20--%3E%20EVAL%0A%20%20SNAP%20--%3E%20EVAL%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("三段式结构的每一环都有独立的失败模式。"),e("strong",null,"分数"),E("是对未来注意力的预测：累积分数偏向早期位置，投票偏向提示末段的局部模式，分布漂移时估计误差直接兑现成误杀。"),e("strong",null,"保护期"),E("是对估计置信度的承认：recent 窗保住「还没来得及积累分数」的位置，sink 禁逐保住配分函数。"),e("strong",null,"不可逆"),E("是与挑页方法的本质分界：删改的是模型看见的集合，挑改的只是 IO——前者是近似生成，后者是近似访存，两者不该用同一个「压缩率」评价。")],-1)),(t(),i(B,null,{default:l(()=>[n(A,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%B8%89%E6%AE%B5%E5%BC%8F%E7%BB%93%E6%9E%84%22%5D%20--%3E%20S%5B%22%E5%88%86%E6%95%B0%EF%BC%9A%E9%A2%84%E6%B5%8B%E6%9C%AA%E6%9D%A5%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20S%20--%3E%20SF%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%E6%97%B6%E8%AF%AF%E6%9D%80%EF%BC%8C%E5%88%86%E6%95%B0%E5%B8%A6%E6%97%A9%E6%9C%9F%20%2F%20%E6%9C%AB%E6%AE%B5%E5%81%8F%E7%BD%AE%22%5D%0A%20%20F%20--%3E%20P%5B%22%E4%BF%9D%E6%8A%A4%E6%9C%9F%EF%BC%9Arecent%20%E7%AA%97%20%2F%20sink%20%E7%A6%81%E9%80%90%22%5D%0A%20%20P%20--%3E%20PF%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E4%BF%9D%E6%8A%A4%E5%A4%AA%E5%A4%9A%EF%BC%8C%E9%A2%84%E7%AE%97%E8%A2%AB%E5%8D%A0%E6%BB%A1%22%5D%0A%20%20F%20--%3E%20I%5B%22%E4%B8%8D%E5%8F%AF%E9%80%86%E5%88%A0%E9%99%A4%22%5D%0A%20%20I%20--%3E%20IF%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E5%85%B3%E9%94%AE%E9%94%AE%E8%A2%AB%E5%88%A0%E5%90%8E%E6%B0%B8%E8%BF%9C%E6%89%BE%E4%B8%8D%E5%9B%9E%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字实例：一个位置每步平均分到 0.01 的注意力，活 1000 步就累积了 10 分；一个刚出现的专名再关键，第一步也只有零点几分。这就是「累积分偏向老位置」的具体样子——recent 保护期正是给新人发的豁免额度。</span></p><p>驱逐还改变缓存的账本形状：被压缩后的页不再随 \\(t\\) 线性增长，容量与带宽的预算（后课）要按压缩后的长度重算；同时压缩页与全量页<a href="/llm/kv-prefix-cache">指纹不同</a>，不能进同一条前缀共享链。</p><p><span class="marginnote">同一预算下启发式之间的差距不是几个点：H2O 论文的消融里，只留最近窗口的版本在多种任务上明显掉队，而「H2 + recent」接近全缓存。选型必须在真实长生成上跑，短补全的困惑度会把滑窗排到第一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>时间错位的负载对预测性驱逐最危险：「先闲聊、最后才问文档第 3 节」的查询，重要性在对话开始时不可见。多轮对话是被驱逐历史最常杀回马枪的地方——被删的键在下一轮又被引用，兜底路径是对丢失段重算 prefill，这笔账要提前算进成本。与量化叠加时误差同向累积：4-bit 噪声稀释针的 logit 优势，驱逐又可能把针直接删掉，两刀要联评。最后，评测只看任务质量与驱逐后的长度分布，吞吐提升不构成采用理由。</p><p><span class="marginnote">为什么多轮对话最容易翻车：第 1 轮提到的合同编号在第 5 轮被追问，若那个键早在第 2 轮被驱逐，模型只能凭残存上下文编一个——表面上像幻觉，根子却在驱逐决策。兜底方案是对丢失段重算 prefill，这笔钱要提前写进预算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可见集驱逐与页池逐出是两本账：前者改模型看见什么，后者只改字节住哪。</li><li>谱系按信号分：位置（窗口+sink）、在线累积（H2O）、提前投票（SnapKV）、查询感知挑页（QUEST）。</li><li>三段式：分数 + 保护期 + 不可逆；每环有独立失败模式。</li><li>选型判据：查询是否已知、提示与生成长度比、可接受的质量损失。</li><li>压缩后的页进不了全量前缀链；与量化联评，验收只看长上下文任务。</li><li>出处：Zhang et al., H2O, NeurIPS 2023；Xiao et al., StreamingLLM, ICLR 2024；Li et al., SnapKV, NeurIPS 2024；Tang et al., QUEST, ICML 2024。</li></ul>',8))])}const D=s(d,[["render",m]]);export{S as __pageData,D as default};
